        <div class="vitals-block" id="vitals-block"><div class="hud-brand-row"><span class="hud-wordmark">MAGIC</span><span class="zone-name" id="zone-name">Η εξωτερική αυλή</span></div>
          <div class="vital-row">${Ut("heart","vital-icon health-icon")}<div class="vital-track" role="meter" aria-label="Ζωή" aria-valuemin="0" aria-valuemax="100" id="health-meter"><div class="vital-fill health-fill" id="health-fill"></div></div><span class="vital-value" id="health-value">100</span></div>
          <div class="vital-row">${Ut("mana","vital-icon mana-icon")}<div class="vital-track" role="meter" aria-label="Μαγική ενέργεια" aria-valuemin="0" aria-valuemax="100" id="mana-meter"><div class="vital-fill mana-fill" id="mana-fill"></div></div><span class="vital-value" id="mana-value">100</span></div>
        </div>
